//! Float-serialization head-to-head: bourne's teju-based writer vs the
//! `ryu` crate vs `serde_json`'s full serializer.
//!
//! Bourne's float formatting is the in-crate teju port (`float.rs`,
//! tables generated by `teju_gen.rs`). This bench is its standing
//! regression harness; audit numbers are read against these groups:
//!
//! - `bourne_write` — the production `to_string` path. The `_same`,
//!   `_four`, and `_reuse_buf` variants at the bottom are diagnostics
//!   with their verdicts recorded inline.
//! - `ryu_direct` — the `ryu` crate's `Buffer::format` assembling the
//!   same `[f0,f1,...]` shape by hand, isolating float formatting from
//!   bourne's punctuation and sink work. Kept as an external ceiling
//!   reference after the teju port superseded the inline-port question
//!   an earlier version of this doc was written to answer.
//! - `serde_json` — `serde_json::to_string` of the same `Vec<f64>`, for
//!   an absolute-scale anchor.
//!
//! Workloads are deliberately float-dominated `Vec<f64>` payloads: ints
//! and structural punctuation are negligible at sizes >=1000 elements,
//! so the bench isolates float cost.

use json_bourne::to_string;

fn main() {
    divan::main();
}

/// Reproducible pseudo-random `Vec<f64>` covering a realistic range
/// of magnitudes. Seeded so successive bench runs are comparable.
//
// Casts here are part of the *fixture content*, not measured code. The
// `as f64` of a u64 is the documented LCG-to-float conversion (top 53
// bits → mantissa) and is the same trick `rand` uses; allowing locally.
#[allow(clippy::cast_precision_loss)]
fn make_floats(n: usize) -> Vec<f64> {
    // Cheap LCG — not for crypto, just for stable per-position values
    // across runs. Avoids pulling in `rand` for a fixture.
    let mut state: u64 = 0xCAFE_BABE_DEAD_BEEF;
    let mut out = Vec::with_capacity(n);
    for i in 0..n {
        state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        // Mix a few magnitudes so the bench isn't all near-1.0:
        // ~10% small (1e-6), ~10% large (1e6), ~80% in [-100, 100].
        let bucket = i % 10;
        let mantissa = (state >> 11) as f64 / (1u64 << 53) as f64; // [0, 1)
        let signed = mantissa.mul_add(2.0, -1.0); // [-1, 1)
        let v = match bucket {
            0 => signed * 1e-6,
            1 => signed * 1e6,
            _ => signed * 100.0,
        };
        out.push(v);
    }
    out
}

mod bourne_write {
    use super::{make_floats, to_string};

    // -------- bourne (production to_string path) --------
    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = make_floats(n);
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench(|| {
                let s = to_string(divan::black_box(&floats)).unwrap();
                divan::black_box(s);
            });
    }
}

mod ryu_direct {
    use super::make_floats;

    // -------- ryu crate direct (external ceiling reference) --------
    // Build the same JSON shape (`[f0,f1,...]`) by hand so the
    // comparison isolates float formatting from punctuation.
    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = make_floats(n);
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench(|| {
                let mut out = String::with_capacity(n * 24);
                let mut buf = ryu::Buffer::new();
                out.push('[');
                let mut first = true;
                for f in divan::black_box(&floats) {
                    if !first {
                        out.push(',');
                    }
                    out.push_str(buf.format(*f));
                    first = false;
                }
                out.push(']');
                divan::black_box(out);
            });
    }
}

mod serde_json {
    use super::make_floats;

    // -------- serde_json (absolute anchor) --------
    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = make_floats(n);
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench(|| {
                let s = ::serde_json::to_string(divan::black_box(&floats)).unwrap();
                divan::black_box(s);
            });
    }
}

// ---------------------------------------------------------------------------
// Diagnostic: same float repeated.
//
// All elements are identical, so the teju math hits the *same* MULTIPLIERS
// entry every time and the digit-write LUT hits stay on the same cache
// lines. If bourne's cliff between n=1000 and n=10000 is data-dependent
// (random input → scattered LUT access pattern → L1d misses), the cliff
// should disappear here. If the cliff persists, the bottleneck is in the
// output-write loop, not the data-dependent inner work.
//
// ANSWERED (audit §4.2): the cliff is data-dependent, but the mechanism is
// branch misprediction, not cache. `bourne_write` loses ~15 % throughput
// from n=1000 to n=10000 while `_same` and `_four` stay flat. Rebuilding
// `write_digits_at_ptr` without the 40 KB QUAD_LUT (200-byte pair table
// only) made n=10000 *12 % slower* and the cliff persisted, refuting the
// L1-conflict hypothesis. `perf stat` per iteration: bourne mispredicts
// 7 050 branches vs serde_json's 843 (8.4×) while retiring 48 % more
// instructions at higher IPC. The cost lives in the data-dependent shape
// selection in `write_f64_to_ptr`.
// ---------------------------------------------------------------------------

mod bourne_write_same {
    use super::to_string;

    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = vec![12345.6789_f64; n];
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench(|| {
                let s = to_string(divan::black_box(&floats)).unwrap();
                divan::black_box(s);
            });
    }
}

mod serde_json_same {
    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = vec![12345.6789_f64; n];
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench(|| {
                let s = ::serde_json::to_string(divan::black_box(&floats)).unwrap();
                divan::black_box(s);
            });
    }
}

// 4 distinct floats cycling — bounded branch-prediction state but still
// multi-magnitude. Tests whether the cliff comes from *unbounded variance*
// vs any variance at all.
mod bourne_write_four {
    use super::to_string;
    fn make(n: usize) -> Vec<f64> {
        let vals = [
            1.234_567_890_123_456_f64,
            9876.54321e-3,
            0.000_123_456_789,
            1.5e15,
        ];
        (0..n).map(|i| vals[i % 4]).collect()
    }
    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = make(n);
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench(|| {
                let s = to_string(divan::black_box(&floats)).unwrap();
                divan::black_box(s);
            });
    }
}

// ---------------------------------------------------------------------------
// Diagnostic: write into a pre-allocated `Vec<u8>` reused across iterations.
//
// `to_string` allocates a fresh `Vec` per call. For n=10000 floats the
// output is ~240 KB and the `Vec::reserve` hint requests ~320 KB, so each
// fresh iteration could in principle pay first-touch page-fault cost.
//
// Empirically (Zen 3 / Ryzen 7 7730U) reusing the buffer is a wash:
// `bourne_write_reuse_buf` 10k ≈ `bourne_write` 10k and
// `serde_json_reuse_buf` 10k ≈ `serde_json` 10k. Conclusion: at n=10k the
// 220 µs/iter wall is in the inner write path, not in allocator overhead.
// Both libraries converge to ~213–221 µs/iter, dominated by memory
// throughput on the ~240 KB output. Keeping the bench so future cache /
// allocator work has a clean reference point.
// ---------------------------------------------------------------------------
mod bourne_write_reuse_buf {
    use super::make_floats;
    use json_bourne::{ByteSink, ToJson};

    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = make_floats(n);
        // Pre-size to the upper bound used by `[f64]::write_json`'s
        // `reserve_hint`: brackets + (max_per_elem + comma) * n.
        let mut buf: Vec<u8> = Vec::with_capacity(2 + n * 33);
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench_local(|| {
                buf.clear();
                let mut sink = ByteSink::new(&mut buf);
                let _ = (divan::black_box(&floats) as &[f64]).write_json(&mut sink);
                divan::black_box(&buf);
            });
    }
}

mod serde_json_reuse_buf {
    use super::make_floats;
    use serde::Serialize as _;

    #[divan::bench(args = [100, 1_000, 10_000])]
    fn bench(bencher: divan::Bencher, n: usize) {
        let floats = make_floats(n);
        let mut buf: Vec<u8> = Vec::with_capacity(2 + n * 33);
        bencher
            .counter(divan::counter::ItemsCount::new(n))
            .bench_local(|| {
                buf.clear();
                let mut ser = ::serde_json::Serializer::new(&mut buf);
                (divan::black_box(&floats) as &[f64])
                    .serialize(&mut ser)
                    .unwrap();
                divan::black_box(&buf);
            });
    }
}
